import fs from 'fs'
const all = JSON.parse(fs.readFileSync('pr59_inline.json','utf8'))
const roots = all.filter(c=>!c.in_reply_to_id)
const byRoot = new Map(roots.map(r=>[r.id,[r]]))
for (const c of all.filter(c=>c.in_reply_to_id)) {
  // replies may chain; GitHub sets in_reply_to_id to the root for review comment threads usually
  let root = c.in_reply_to_id
  while (!byRoot.has(root)) {
    const parent = all.find(x=>x.id===root)
    if (!parent || !parent.in_reply_to_id) break
    root = parent.in_reply_to_id
  }
  if (byRoot.has(root)) byRoot.get(root).push(c); else byRoot.set(root,[c])
}
const idx = Number(process.argv[2] ?? -1)
const list = [...byRoot.entries()]
if (idx < 0) {
  list.forEach(([id,arr],i)=>{
